<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Accessor\MessageUrgentAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the MessageUrgentAccessor trait.
 *
 * Covers null default, string/VO assignment via withUrgent,
 * getUrgent/urgent accessors, and isUrgentChanged with/without original.
 */
class MessageUrgentAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withUrgent creates a new instance with the Urgent set
     * from a string value, and getUrgent returns the primitive string.
     */
    public function testWithUrgentFromString(): void
    {
        // Arrange
        $holder = new ImplWithMessageUrgentAccessorUnitTest();

        // Act
        $result = $holder->withUrgent(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isUrgent());
    }
    /**
     * Asserts that withurgent has access to the value object
     * from a string value, and getUrgent returns the primitive string.
     */
    public function testWithUrgentFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithMessageUrgentAccessorUnitTest();

        // Act
        $result = $holder->withUrgent(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->urgent()->value());
    }
    public function testChangedUrgent(): void
    {
        // Arrange
        $holder = new ImplWithMessageUrgentAccessorUnitTest()->withUrgent(true);
        $original = $holder->withUrgent(true);
        $same = $holder->withUrgent(true);
        $modified = $holder->withUrgent(false);

        // Act
        $withSame = $original->isUrgentChanged($same);
        $withDiferent = $original->isUrgentChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithMessageUrgentAccessorUnitTest
{
    use MessageUrgentAccessor;
}
